# replace url safe base64
clean_str = clean_str.replace("-", "+").replace("_", "/")
# pad
while len(clean_str) % 4 != 0:
    clean_str += "="

try:
    decoded = base64.b64decode(clean_str)
    print("Decoded length:", len(decoded))
    print("Decoded hex header:", decoded[:15].hex())
    
    # Try decompressing with standard zlib
    decompressed = zlib.decompress(decoded)
    print("Decompressed successfully!")
    print(decompressed.decode('utf-8'))
except Exception as e:
    print("Failed to decompress:", str(e))
